.pko-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pko-root,.pko-root *,.pko-root *::before,.pko-root *::after{box-sizing:border-box}
.pko-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pko-root img{display:block;border:0;max-width:none}
.pko-root [hidden]{display:none!important}
.pko-root .nI40_11526_17_13493{align-content:stretch;display:flex;height:40.6px;align-items:center;justify-content:space-between;padding-left:4px;position:relative;flex-shrink:0;width:100%}
.pko-root .nI40_11526_17_13494{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:14px;color:var(--wa-text, #fff);white-space:nowrap;width:49px}
.pko-root .nI40_11526_17_13495{position:relative;flex-shrink:0;width:24px;height:24px}
.pko-root .x135{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pko-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pko-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pko-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pko-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pko-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pko-root[data-theme="light"] .nI40_11526_17_13494{color:var(--wa-text, #10231d)}
